+            m_battle_return_hook_ids = UObjectGlobals::RegisterHook(
+                m_battle_return_hook_path, pre_cb, post_cb, nullptr);
+        }
+        catch (const std::exception& error)
+        {
+            Output::send<LogLevel::Error>(STR(
+                "[HorseMod] Player Match battle-return hook registration "
+                "failed: {}\n"), RC::to_generic_string(error.what()));
