+        m_battle_return_hook_registered = true;
+        Output::send<LogLevel::Default>(STR(
+            "[HorseMod] Player Match battle-return hook registered "
+            "pre={} post={}\n"), m_battle_return_hook_ids.first,
+            m_battle_return_hook_ids.second);
