+[[nodiscard]] inline constexpr bool OnlinePrefixCatchupWatchdogExpired(
+    FrameCoordinate baseline, FrameCoordinate completed_native,
+    std::uint64_t maximum_native_frames = 120) noexcept
+{
+    return baseline.generation != 0
+        && completed_native.generation == baseline.generation
+        && completed_native.frame >= baseline.frame
+        && completed_native.frame - baseline.frame >= maximum_native_frames;
+}
+
+[[nodiscard]] inline constexpr bool NeedsOnlinePrefixConfirmationDrain(
+    std::size_t prefix_frames, std::int32_t gekko_confirmed_frame,
+    FrameCoordinate next, FrameCoordinate completed_native) noexcept
+{
+    if (prefix_frames == 0 || next <= completed_native
+        || prefix_frames - 1
+            > static_cast<std::size_t>((std::numeric_limits<std::int32_t>::max)()))
+        return false;
+    return gekko_confirmed_frame
+        < static_cast<std::int32_t>(prefix_frames - 1);
+}
