@@ -8,10 +8,11 @@

 namespace Horse::Deterministic
 {
-// ALuxBattleGameMode::TerminateBattle is a two-sided native boundary. The
-// pre-hook is the last point at which the active coordinator contract is
-// guaranteed readable, while the post-hook is the first point after stock
-// BattleManager teardown. Retain only the value identity between them.
+// Player Match can publish its lobby transition before the later
+// ALuxBattleGameMode::TerminateBattle call. Arm at the earliest definitive
+// battle-return request (or at TerminateBattle as a fallback), quiesce owned
+// simulation immediately, and retain only the value identity until a native
+// termination or presence-exit boundary proves that stock teardown completed.
 class OnlineSceneExitGate final
 {
 public:
